using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public sealed class DiscountAcceptanceTests
{
    private static int ChargedFor(LoyaltyTier tier, int subtotalCents) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    // Bronze customer is charged 9500 cents for a 10000 cent basket
    [Fact]
    public void S1_BronzeBasketOf10000CentsIsCharged9500Cents() =>
        Assert.Equal(9500, ChargedFor(LoyaltyTier.Bronze, 10000));

    // Silver customer is charged 9000 cents for a 10000 cent basket
    [Fact]
    public void S2_SilverBasketOf10000CentsIsCharged9000Cents() =>
        Assert.Equal(9000, ChargedFor(LoyaltyTier.Silver, 10000));

    // Gold customer is charged 8500 cents for a 10000 cent basket
    [Fact]
    public void S3_GoldBasketOf10000CentsIsCharged8500Cents() =>
        Assert.Equal(8500, ChargedFor(LoyaltyTier.Gold, 10000));
}
E
